const icons={shield:'M12 3 20 6v6c0 5-8 9-8 9s-8-4-8-9V6l8-3M8 12h3l2-4 2 8 2-4h2',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',data:'M20 6c0 2-16 2-16 0s16-2 16 0ZM4 6v12c0 3 16 3 16 0V6M4 12c0 3 16 3 16 0',chart:'M4 4v16h17M8 15v-4M13 15V7M18 15v-7',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',scan:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5M7 12h3l2-5 3 10 2-5h2',book:'M4 4h6l2 2 2-2h6v16h-6l-2 1-2-1H4ZM12 6v15',arrow:'M5 12h14M14 7l5 5-5 5',upload:'M12 16V3M7 8l5-5 5 5M4 16v5h16v-5',download:'M12 3v13M7 11l5 5 5-5M4 17v4h16v-4',play:'m8 4 12 8-12 8V4',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm6-2 6 6',info:'M12 11v6M12 7v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',check:'m5 12 4 4L20 5',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM12 12h.01',activity:'M2 12h5l3-8 4 16 3-8h5',bolt:'m13 2-9 12h7l-1 8L21 9h-8l1-7',refresh:'M20 8a8 8 0 1 0 0 8M20 3v5h-5',menu:'M4 6h16M4 12h16M4 18h16',close:'m5 5 14 14M19 5 5 19',code:'m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18',flask:'M8 3h8M9 3v7L3 20c0 1 18 1 18 0l-6-10V3M7 14h10',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',external:'M14 3h7v7M21 3 10 14M10 3H3v18h18v-7',file:'M14 2H5v20h14V7l-5-5ZM14 2v6h5M8 12h8M8 16h6'};
const I=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const pct=(n,d=1)=>(100*n).toFixed(d)+'%';
const fmt=n=>Number(n).toLocaleString('en-US');
const valueFmt=v=>typeof v==='number'?(Number.isInteger(v)?fmt(v):Number(v.toFixed(3))):esc(v);
const state={view:'workflows',rows:FlowData.demo(),file:'synthetic_network_flows.csv',demo:true,label:'label',excluded:new Set,normalLabels:['Normal'],run:null,worker:null,busy:false,progress:0,progressText:'Preparing dataset',error:'',page:0,search:'',filter:'all',selected:0,local:null,prediction:null,formValues:{},menu:false,predictRevision:0};
const views={workflows:['Workflows','Run an analysis from input to investigation.'],batch:['Batch scoring','Apply your fitted model to new flow records.'],reviews:['Review queue','Turn model signals into documented decisions.'],history:['Experiment history','Resume saved models and review completed runs.'],overview:['Overview','Your network flows, explained.'],dataset:['Dataset','Start with the right data.'],evaluation:['Model evaluation','Measure what your model gets right.'],explainability:['Explainability','Understand the prediction.'],analyzer:['Flow analyzer','Put a network flow to the test.'],notes:['Project notes','A transparent approach to network intelligence.']};
function notify(message){let t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),3600)}
function navigate(view){state.view=view;state.menu=false;state.error='';render();window.scrollTo({top:0,behavior:'instant'});if(view==='explainability'&&state.run)explainSelected()}
function classTag(v){return `<span class="tag class-${v.toLowerCase()}"><span class="dot" style="background:${v==='Normal'?'#90b881':'#d0aa70'}"></span>${v}</span>`}
function shell(content){const nav=[['workflows','bolt','Workflows'],['overview','grid','Overview'],['dataset','data','Dataset'],['evaluation','chart','Model evaluation'],['explainability','layers','Explainability'],['analyzer','scan','Flow analyzer'],['batch','data','Batch scoring'],['reviews','shield','Review queue'],['history','clock','Experiment history'],['notes','book','Project notes']];return `<div class="layout"><div class="mobile-scrim ${state.menu?'open':''}" data-action="menu"></div><aside class="sidebar ${state.menu?'open':''}"><div class="brand">${I('shield','brand-mark')}<div>FlowLens<small>NETWORK INTELLIGENCE</small></div></div><div class="workspace-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(([key,icon,title])=>`<button data-view="${key}" class="${state.view===key?'active':''}" ${state.view===key?'aria-current="page"':''}>${I(icon)}${title}${key==='analyzer'?'<span class="count">XAI</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><div class="shield-label">${I('shield')}Private by design</div><p>Your dataset and model stay in this browser. Saved workflows stay on this device. No dataset is uploaded to a server.</p></div><div class="profile"><div class="avatar">FL</div><div><strong>Research workspace</strong><small>Educational project · 2026</small></div></div></div></aside><header class="topbar"><div class="breadcrumb"><button class="icon-btn menu-btn" data-action="menu" aria-label="Toggle navigation">${I('menu')}</button><span>Workspace</span>${I('chevron')}<strong>${views[state.view][0]}</strong></div><div class="top-actions"><span class="offline"><i class="dot"></i>Browser-local processing</span><span class="tag">${I('flask')}Educational prototype</span><button class="icon-btn" data-view="notes" aria-label="About this project">${I('info')}</button></div></header><main class="main"><div class="page-heading"><div><div class="eyebrow">EXPLAINABLE AI · INTRUSION DETECTION</div><h1>${views[state.view][0]}</h1><p>${views[state.view][1]}</p></div><div class="actions">${state.run?`<button class="btn" data-action="export">${I('download')}Export results</button>`:`<button class="btn" data-action="sample">${I('download')}Sample CSV</button>`}<button class="btn primary" data-view="dataset">${I('upload')}Upload dataset</button></div></div>${state.error?`<div class="error-note" role="alert">${esc(state.error)}</div>`:''}${state.busy?progressPanel():''}${content}<footer class="footer"><span>FlowLens · Explainable AI for Network Intrusion Detection</span><div class="footer-right"><span>UIT · Karnavati University</span><button data-view="notes">Methodology ${I('external')}</button></div></footer></main></div>`}
function banner(){return `<div class="banner">${I('info')}<span><strong>${state.demo?'Synthetic demonstration dataset.':'Offline educational analysis.'}</strong> ${state.demo?'Results validate the workflow, not real-world detection performance.':'Predictions depend on your dataset and label mapping; validate with independent evidence.'}</span><span class="tag ${state.demo?'orange':''}">${state.demo?'Demo data':'User-provided data'}</span></div>`}
function progressPanel(){return `<div class="progress-panel" role="status"><span>${I('refresh')}</span><div class="progress-info"><div class="progress-title" id="progress-title">${esc(state.progressText)} · ${state.progress}%</div><div class="progress-track"><i id="progress-bar" style="width:${state.progress}%"></i></div></div><button class="btn" data-action="cancel">Cancel training</button></div>`}
function stats(){const m=state.run.scores;return `<div class="stats">${[['Accuracy',m.accuracy,'target','All held-out records','Test-set agreement'],['Precision',m.precision,'shield','Suspicious class','Positive predictive value'],['Recall',m.recall,'activity','Suspicious class',m.fn+' suspicious flows missed'],['F1-score',m.f1,'bolt','Suspicious class','Precision–recall balance']].map(([label,value,icon,foot,desc])=>`<div class="stat"><div class="stat-head">${label}<span class="stat-icon">${I(icon)}</span></div><div class="stat-value">${(value*100).toFixed(1)}<small>%</small></div><div class="stat-footer"><b class="${label==='Recall'&&value<.8?'warn':''}">${desc}</b></div><div class="stat-footer">${foot}</div></div>`).join('')}</div>`}
function matrix(){const s=state.run.scores;return `<div class="card"><div class="card-title"><div><h2>Confusion matrix</h2><p class="card-sub">Where predictions meet actual labels</p></div><span class="tag">${s.total} test flows</span></div><div class="matrix-wrap"><div class="axis-y">ACTUAL LABEL</div><div><div class="matrix-area"><span></span><span>Normal</span><span>Suspicious</span><span class="row-label">Normal</span><div class="matrix-cell tn"><strong>${fmt(s.tn)}</strong><small>True negatives</small></div><div class="matrix-cell error"><strong>${fmt(s.fp)}</strong><small>False positives</small></div><span class="row-label">Suspicious</span><div class="matrix-cell error"><strong>${fmt(s.fn)}</strong><small>False negatives</small></div><div class="matrix-cell tp"><strong>${fmt(s.tp)}</strong><small>True positives</small></div></div><div class="axis-x">PREDICTED LABEL</div></div></div><div class="card-foot"><div class="legend"><span><i></i>Correct prediction</span><span><i class="ochre"></i>Misclassification</span></div><span>Threshold: 0.50</span></div></div>`}
function importance(full=false){let list=state.run.importance.slice(0,full?40:6),max=Math.max(.01,...list.map(x=>Math.abs(x.importance)));return `<div class="card"><div class="card-title"><div><h2>What influences the model?</h2><p class="card-sub">Global permutation feature importance</p></div>${full?'<span class="tag">3 shuffles / feature</span>':`<button class="text-btn" data-view="explainability">Explore ${I('arrow')}</button>`}</div><div class="bars">${list.map(x=>`<div class="bar-row"><span class="bar-name" title="${esc(x.name)}">${esc(x.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${100*Math.abs(x.importance)/max}%;${x.importance<0?'background:#c8bbaa':''}"></div></div><span class="bar-num">${x.importance.toFixed(3)}</span></div>`).join('')}</div><div class="bar-axis"><span>0</span><span>${(max/2).toFixed(2)}</span><span>${max.toFixed(2)}</span></div><div class="card-foot"><span>Decrease in test macro-F1 · greater is more influential</span>${full?'':`<span>${state.run.features.length} features</span>`}</div>${full?'<p class="metric-note">Negative values mean shuffling improved the score. Bars show magnitude; signed values are reported. Correlation can share or mask importance.</p>':''}</div>`}
function flowTable(){let all=state.run.tests.filter(t=>(state.filter==='all'||(state.filter==='errors'?t.actual!==t.predicted:t.predicted===state.filter))&&FlowWorkflow.matchesFlow(t,state.search)),pages=Math.max(1,Math.ceil(all.length/5));state.page=Math.min(state.page,pages-1);let tests=all.slice(state.page*5,state.page*5+5),schema=state.run.schema,cols=schema.slice(0,2);return `<section class="card table-card"><div class="table-header"><div><h2>Evaluated flows</h2><p>A closer look at held-out predictions</p></div><div class="table-tools"><div class="input-wrap">${I('search')}<input aria-label="Search evaluated flows" id="flow-search" placeholder="Search flows…" value="${esc(state.search)}"></div><select class="control" id="flow-filter" aria-label="Filter flows">${[['all','All predictions'],['Normal','Normal'],['Suspicious','Suspicious'],['errors','Misclassified']].map(([v,t])=>`<option value="${v}" ${v===state.filter?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="table-scroll"><table><thead><tr><th>Flow ID</th>${cols.map(s=>`<th>${esc(s.name)}</th>`).join('')}<th>Actual label</th><th>Prediction</th><th>Suspicious probability</th><th></th></tr></thead><tbody>${tests.map(t=>`<tr><td class="flow-id">FL-${String(t.id).padStart(4,'0')}</td>${cols.map(s=>`<td>${valueFmt(t.values[s.name])}</td>`).join('')}<td>${classTag(t.actual)}</td><td>${classTag(t.predicted)}</td><td><div class="prob-cell">${pct(t.probability)}<span class="prob-line"><i style="width:${t.probability*100}%;${t.probability>=.5?'background:#d1b281':''}"></i></span></div></td><td><button class="text-btn" data-explain="${t.id}" aria-label="Explain flow ${t.id}">Explain ${I('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="7" style="text-align:center;padding:28px">No matching flows. Try another filter.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${all.length?'Showing '+(state.page*5+1)+'–'+Math.min(state.page*5+5,all.length):'Showing 0'} of ${fmt(all.length)} flows</span><div class="pager"><button data-page="${state.page-1}" aria-label="Previous page" ${state.page===0?'disabled':''}>‹</button><button class="current" aria-label="Current page">${state.page+1}</button><span> / ${pages}</span><button data-page="${state.page+1}" aria-label="Next page" ${state.page===pages-1?'disabled':''}>›</button></div></div></section>`}
function overview(){if(!state.run)return state.demo?welcome():banner()+requireModel();return `${banner()}<div class="section-head"><div><h2>Model performance</h2><p>Measured on ${fmt(state.run.testCount)} unseen flows · ${esc(state.file)}</p></div><span class="tag"><i class="dot"></i>Model trained</span></div>${stats()}<div class="grid2">${matrix()}${importance()}</div>${flowTable()}<div class="insight-strip"><div class="insight-icon">${I('layers')}</div><div><h3>A prediction is just the beginning.</h3><p>Inspect the feature changes behind any flow, or test your own inputs.</p></div><button class="btn" data-view="analyzer">Analyze a flow ${I('arrow')}</button></div>`}
function welcome(){return `${banner()}<div class="intro-grid"><section class="welcome"><div class="eyebrow">FROM CLASSIFICATION TO UNDERSTANDING</div><h2>See the signal.<br>Understand the decision.</h2><p>Train a model on network-flow records, explore its errors, and see which features influence each prediction.</p><button class="btn" data-action="train" ${state.busy?'disabled':''}>${I('play')}Train demo model</button><div class="welcome-decor"></div></section><section class="card"><h2>Your analysis workspace</h2><p class="card-sub">A complete, reproducible flow from CSV to explanation</p><div class="quick-actions"><button data-view="dataset">${I('data')}<span><strong>Bring your dataset</strong><small>Upload a labelled CSV or use 900 synthetic flows</small></span>${I('arrow')}</button><button data-view="notes">${I('book')}<span><strong>Understand the methodology</strong><small>Random Forest · global importance · local sensitivity</small></span>${I('arrow')}</button></div></section></div><div class="stats">${[['900','Synthetic flows','data'],['150','Decision trees','layers'],['75 / 25','Train / test split','chart'],['100%','Browser-local processing','shield']].map(([v,l,i])=>`<div class="stat"><div class="stat-head">${l}<span class="stat-icon">${I(i)}</span></div><div class="stat-value">${v}</div><div class="stat-footer">${l==='Synthetic flows'?'Generated sample; no live traffic':l==='Decision trees'?'Balanced class weights':l==='Train / test split'?'Stratified · fixed seed 42':'No server-side dataset uploads'}</div></div>`).join('')}</div><div class="card about-section"><div class="section-head"><h2>One transparent workflow</h2><span class="step-tag">BUILT FROM YOUR PROJECT REPORT</span></div>${pipeline()}<p>This workspace implements the report’s offline binary classification workflow. Train the bundled demo, or review your own label mapping before running an experiment.</p></div>`}
function pipeline(){return `<div class="pipeline">${[['01','Load & inspect','Labelled CSV records with numerical and categorical features.'],['02','Prepare & train','Training-only imputation, one-hot encoding, and a Random Forest.'],['03','Evaluate','Held-out metrics and a fully labelled confusion matrix.'],['04','Explain','Permutation importance and one-feature-at-a-time sensitivity.']].map(([n,t,p])=>`<div><b>${n}</b><strong>${t}</strong><p>${p}</p></div>`).join('')}</div>`}
function dataset(){let headers=Object.keys(state.rows[0]),labels=[...new Set(state.rows.map(r=>String(r[state.label]??'')))].sort(),n=state.rows.filter(r=>state.normalLabels.map(FlowWorkflow.token).includes(FlowWorkflow.token(r[state.label]))).length,features=headers.filter(h=>h!==state.label);return `${banner()}<div class="two-thirds"><section class="card"><div class="card-title"><div><h2>Dataset source</h2><p class="card-sub">Choose a labelled network-flow CSV</p></div><span class="step-tag">01 · INPUT</span></div><label class="upload-zone" id="drop-zone" for="csv-file">${I('upload')}<strong>Drop a CSV here, or click to browse</strong><p>Up to 5 MB · 10,000 records · 80 columns</p><span class="tag">CSV files only</span></label><input type="file" id="csv-file" accept=".csv,text/csv"><div class="section-head"><div style="display:flex;gap:10px;align-items:center">${I('file')}<div><h3 class="csv-name" title="${esc(state.file)}">${esc(state.file)}</h3><p>${state.demo?'Seeded synthetic demonstration':'User-provided dataset · provenance unverified'}</p></div></div><button class="text-btn" data-action="reset-demo">Use demo ${I('refresh')}</button></div><div class="data-summary"><div class="mini-stat"><strong>${fmt(state.rows.length)}</strong><small>Total records</small></div><div class="mini-stat"><strong>${headers.length}</strong><small>Columns</small></div><div class="mini-stat"><strong>${features.filter(x=>!state.excluded.has(x)).length}</strong><small>Selected features</small></div></div><details><summary>CSV format and data guidance</summary><p>Use a header row and 20–10,000 labelled records with at least 4 records per class. Numeric columns accept finite numbers; blanks are imputed. Categorical features allow 30 training categories per column. Match feature definitions and units across your records.</p><p>Remove identifiers, timestamps and leaked target information before evaluation. Duplicate or related records can inflate scores across a random split. Demo feature units are milliseconds, bytes, packet counts, packets/second, a 0–1 SYN ratio, and a failed-login count.</p><button class="text-btn" data-action="sample">Download example CSV ${I('download')}</button></details></section><section class="card"><div class="card-title"><div><h2>Prepare your experiment</h2><p class="card-sub">Verify the target before training</p></div><span class="step-tag">02 · CONFIGURE</span></div><div class="field"><label for="label-column">Target label column</label><select id="label-column" ${state.busy?'disabled':''}>${headers.map(h=>`<option ${h===state.label?'selected':''} value="${esc(h)}">${esc(h)}</option>`).join('')}</select></div><div style="margin-top:18px"><h3>Map labels to Normal</h3><p class="card-sub">Select normal/benign labels. All others become Suspicious.</p><div class="field-set">${labels.slice(0,50).map(v=>`<label class="check-chip"><input type="checkbox" data-normal="${esc(v)}" ${state.normalLabels.includes(v)?'checked':''} ${state.busy?'disabled':''}>${esc(v)||'(empty)'}</label>`).join('')}</div>${labels.length>50?'<p class="note orange">More than 50 target values. Choose a categorical label column, not an identifier.</p>':''}</div><div class="data-summary" style="grid-template-columns:1fr 1fr"><div class="mini-stat"><strong>${fmt(n)}</strong><small>Normal records</small></div><div class="mini-stat"><strong>${fmt(state.rows.length-n)}</strong><small>Suspicious records</small></div></div><div class="note">75% training / 25% test · stratified split · seed 42. Training-only median/mode imputation and one-hot encoding. Unknown categories map to an all-zero encoded group.</div><button class="btn primary" data-action="train" style="width:100%;margin-top:17px" ${state.busy?'disabled':''}>${I('play')}${state.busy?'Training in progress…':'Train & evaluate model'}</button></section></div><section class="card about-section"><div class="section-head"><div><h2>Feature selection</h2><p>Review identifiers and leakage-prone columns. Constant features are removed using training data only.</p></div><div class="actions"><button class="btn" data-wf="clean" ${WF.working()?'disabled':''}>${I('refresh')}Remove duplicate records</button><span class="tag">${features.filter(x=>!state.excluded.has(x)).length} / 40 max</span></div></div><div class="field-set">${features.map(h=>`<label class="check-chip"><input type="checkbox" data-feature="${esc(h)}" ${state.excluded.has(h)?'':'checked'} ${state.busy?'disabled':''}>${esc(h)}</label>`).join('')}</div></section><section class="card table-card"><div class="table-header"><div><h2>Dataset preview</h2><p>First 8 records · raw values before preprocessing</p></div><span class="tag">${state.demo?'Synthetic':'Uploaded'} CSV</span></div><div class="table-scroll"><table><thead><tr><th>#</th>${headers.map(h=>`<th>${esc(h)}${h===state.label?' · target':''}</th>`).join('')}</tr></thead><tbody>${state.rows.slice(0,8).map((r,i)=>`<tr><td>${i+1}</td>${headers.map(h=>`<td>${esc(r[h])||'<span class="muted">missing</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function requireModel(){return `<div class="empty">${I('layers')}<h2>Your model is waiting to be trained</h2><p>Start with the synthetic demonstration dataset or upload your own labelled flows. Evaluation and explanations will appear after training.</p><button class="btn primary" data-action="train" ${state.busy?'disabled':''}>${I('play')}${state.demo?'Train demo model':'Train selected dataset'}</button><button class="btn" data-view="dataset" style="margin-left:8px">Choose dataset</button></div>`}
function evaluation(){if(!state.run)return requireModel();let r=state.run,s=r.scores;return `${banner()}${stats()}<div class="grid2">${matrix()}<section class="card"><div class="card-title"><div><h2>Experiment details</h2><p class="card-sub">A reproducible held-out evaluation</p></div><span class="tag">Seed 42</span></div><div class="model-facts">${[['Classifier','Random Forest'],['Trees','150 · balanced weights'],['Training records',fmt(r.trainCount)],['Test records',fmt(r.testCount)],['Split strategy','Stratified 75 / 25'],['Encoded dimensions',r.dimensions],['Maximum tree depth','12'],['Minimum leaf size','2 records'],['Macro-F1',r.scores.macroF1.toFixed(4)],['Decision threshold','0.50']].map(([a,b])=>`<div class="fact"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div></section></div><div class="two-thirds"><section class="card"><h2>Data quality review</h2><div class="model-facts">${[['Missing selected-feature cells',fmt(r.missing)],['Duplicate selected inputs + label',fmt(r.duplicates)],['Removed constant/empty columns',r.dropped.length],['Normal / Suspicious records',r.classCounts.map(fmt).join(' / ')]].map(([a,b])=>`<div class="fact"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>${r.dropped.length?`<p class="metric-note">Removed: ${r.dropped.map(esc).join(', ')}</p>`:''}${r.duplicates?'<p class="note orange" style="margin-top:16px">Duplicates can cross the train/test split and inflate performance. Deduplicate or use a group-based split before drawing conclusions.</p>':''}<p class="metric-note" style="margin-top:16px">Use the dataset cleanup action to remove duplicate selected-feature and label records before training. Identifier and leakage review remains your responsibility.</p></section><section class="card"><h2>Read the errors, too</h2><p class="card-sub" style="line-height:1.8;margin:13px 0">${fmt(s.fn)} Suspicious flows were classified as Normal, and ${fmt(s.fp)} Normal flows were flagged as Suspicious. Accuracy alone does not describe these tradeoffs.</p><div class="note orange">${state.demo?'This synthetic run is a software demonstration. It does not reproduce the report’s 89.33% result or establish real-world detection performance.':'Random held-out results can be optimistic for related sessions or time periods. Use documented group/time-based evaluation before operational claims.'}</div></section></div>${flowTable()}`}
function predictionBox(result,label='MODEL OUTPUT'){return `<div class="prediction ${result.probability>=.5?'suspicious':''}"><div class="eyebrow">${label}</div><span class="tag" style="background:#ffffff12;color:#b7cbb0">${I('scan')}Random Forest · 150 trees</span><h2>${result.prediction}</h2><p>${result.probability>=.5?'This flow resembles the Suspicious class in this model.':'This flow resembles the Normal class in this model.'}</p><div class="big-prob">${pct(result.probability)}</div><p>Estimated Suspicious probability</p><div class="prob-meter"><i style="width:${result.probability*100}%"></i></div><div style="display:flex;justify-content:space-between;font-size:9px;color:#9fb398"><span>0 · Normal</span><span>Threshold 0.50</span><span>1 · Suspicious</span></div></div>`}
function sensitivity(result){let max=Math.max(.01,...result.factors.map(f=>Math.abs(f.delta)));return `<section class="card"><div class="card-title"><div><h2>Local feature sensitivity</h2><p class="card-sub">One feature replaced with a typical training value</p></div></div><div class="legend small" style="font-size:9px;color:#98a18f"><span><i></i>Toward Normal</span><span><i class="ochre"></i>Toward Suspicious</span></div>${result.factors.map(f=>{let w=Math.abs(f.delta)/max*48;return `<div class="sensitivity-row"><div class="sensitivity-head"><strong>${esc(f.name)}</strong><span class="${f.delta<0?'negative-label':'positive-label'}">${f.delta>=0?'+':''}${(f.delta*100).toFixed(2)} pp</span></div><div class="sensitivity-meter"><i class="${f.delta<0?'negative':''}" style="left:${f.delta<0?50-w:50}%;width:${w}%"></i></div><div class="sensitivity-detail"><span>Observed: ${valueFmt(f.value??'missing')}</span><span>Reference: ${valueFmt(f.typical)}</span></div></div>`}).join('')}<p class="metric-note" style="line-height:1.8">Δ = original probability − probability after replacement. Positive values support Suspicious relative to this reference. These changes are independent perturbations, not additive contributions or causal evidence.</p></section>`}
function explainability(){if(!state.run)return requireModel();let test=state.run.tests[state.selected];return `${banner()}<div class="two-thirds">${importance(true)}<section class="card"><h2>Two views of model behavior</h2><p class="card-sub" style="line-height:1.9;margin:16px 0"><strong>Global importance</strong> shuffles each original feature on the held-out partition and measures the reduction in macro-F1. Values are averaged over 3 shuffles.</p><p class="card-sub" style="line-height:1.9;margin:16px 0"><strong>Local sensitivity</strong> replaces one selected flow’s feature at a time with its training median or mode and measures the probability change.</p><div class="note orange">Explanations describe the fitted model. They do not establish what caused an intrusion. Correlated features can mask importance or produce unrealistic replacement flows.</div></section></div><div class="section-head"><div><h2>Explain an individual flow</h2><p>Select any held-out record and inspect its prediction</p></div><span class="tag">${state.run.testCount} test records</span></div><div class="flow-select"><div class="field"><label for="flow-select">Held-out test flow</label><select id="flow-select">${state.run.tests.map((t,i)=>`<option value="${i}" ${i===state.selected?'selected':''}>FL-${String(t.id).padStart(4,'0')} · Actual: ${t.actual} · Predicted: ${t.predicted}${t.actual!==t.predicted?' · Misclassified':''}</option>`).join('')}</select></div><button class="btn" data-action="use-flow">${I('scan')}Edit in flow analyzer</button></div><div id="local-result">${state.local?localResults(test):'<div class="note">Calculating feature sensitivity…</div>'}</div>`}
function localResults(test){return `<div class="two-thirds">${sensitivity(state.local)}<div>${predictionBox(state.local,'HELD-OUT FLOW · FL-'+String(test.id).padStart(4,'0'))}<div class="card"><div class="section-head"><h3>Ground-truth label</h3>${classTag(test.actual)}</div><p class="card-sub">${test.actual===test.predicted?'The model agrees with this dataset label.':'The model disagrees with this dataset label.'}</p><div class="note" style="margin-top:18px">A Suspicious prediction is a model signal, not proof of an attack. Probabilities have not been calibrated.</div></div></div></div>`}
function analyzer(){if(!state.run)return requireModel();return `${banner()}<div class="two-thirds"><section class="card"><div class="card-title"><div><h2>Custom flow features</h2><p class="card-sub">Use the same feature definitions and units as your CSV</p></div><button class="text-btn" data-action="reset-form">Reset ${I('refresh')}</button></div><form id="analyze-form"><div class="form-grid single-mobile">${state.run.schema.map((s,i)=>`<div class="field"><label for="feature-${i}">${esc(s.name)}</label>${s.type==='numeric'?`<input type="number" step="any" id="feature-${i}" data-input="${esc(s.name)}" value="${esc(state.formValues[s.name]??s.typical)}" required><small>Observed training range: ${valueFmt(s.min)} – ${valueFmt(s.max)}</small>`:`<select id="feature-${i}" data-input="${esc(s.name)}">${s.categories.map(c=>`<option value="${esc(c)}" ${String(state.formValues[s.name]??s.typical)===c?'selected':''}>${esc(c)}</option>`).join('')}</select><small>Choose an observed training category</small>`}</div>`).join('')}</div><div class="note" style="margin-top:23px">Inputs are interpreted as one flow record. No packets are captured and no connections are blocked. Missing values during training use training-only median/mode imputation.</div><button class="btn primary" type="submit" style="width:100%;margin-top:17px" ${state.busy?'disabled':''}>${I('scan')}Analyze flow</button></form></section><div class="result-card" id="prediction-result">${analyzerResults()}</div></div>${state.prediction?`<div id="custom-sensitivity">${sensitivity(state.prediction)}</div>`:'<div id="custom-sensitivity"></div>'}`}
function analyzerResults(){if(!state.prediction)return `<section class="card empty" style="margin:0;padding:60px 25px">${I('scan')}<h2>Every flow has a story.</h2><p>Enter the flow’s values and run an analysis to see its predicted class, probability, and local feature sensitivity.</p><span class="tag">Ready when you are</span></section>`;let out=state.run.schema.filter(s=>s.type==='numeric'&&(Number(state.formValues[s.name])<s.min||Number(state.formValues[s.name])>s.max));return `${predictionBox(state.prediction,'CUSTOM FLOW ANALYSIS')}<section class="card"><h3>Interpret with care</h3><p class="card-sub" style="line-height:1.9;margin:12px 0">This is an uncalibrated model estimate. Confirm important results using trusted logs and analyst knowledge.</p>${out.length?`<div class="note orange">Outside observed training range: ${out.map(s=>esc(s.name)).join(', ')}. Predictions may be unreliable for these inputs.</div>`:''}<button class="btn" data-action="export-flow" style="width:100%;margin-top:14px">${I('download')}Export this analysis</button></section>`}
function notes(){return `<div class="card about-section"><div class="section-head"><div><h2>Explainable AI for Network Intrusion Detection</h2><p>An educational implementation based on your attached project report</p></div><span class="tag">OFFLINE PROTOTYPE</span></div><p>FlowLens classifies labelled network-flow records into Normal and Suspicious and helps you inspect the model’s behavior. It implements the report’s data ingestion, training, evaluation, permutation importance, local sensitivity, and custom-flow workflow.</p>${pipeline()}<p>The report describes a Python / scikit-learn / Streamlit prototype. This website uses a browser-native JavaScript Random Forest in a Web Worker, so training and predictions work without a Python server. It is a separate implementation; its results are not expected to match scikit-learn or the report’s preliminary results.</p></div><div class="grid2"><section class="card"><h2>Model and preprocessing</h2><ul class="steps-list"><li>150 bootstrapped classification trees; seed 42.</li><li>Balanced class weights computed from training records.</li><li>Random √p feature selection at each node.</li><li>Weighted Gini splits with up to 10 quantile candidates.</li><li>Maximum depth 12; minimum leaf size 2.</li><li>75 / 25 stratified split (class counts rounded).</li><li>Training-only constant removal, median/mode imputation and one-hot encoding.</li><li>Predicted probability averages weighted leaf probabilities. Decision threshold: 0.50.</li></ul></section><section class="card"><h2>Data and experiment provenance</h2><p class="card-sub" style="line-height:1.9;margin:15px 0">The bundled 900-row sample is generated with seed 42 for demonstration only. It contains duration, protocol, byte counts, packet counts/rates, SYN ratio and failed logins. Its labels and patterns are synthetic.</p><div class="note orange">The report’s preliminary 89.33% accuracy belongs to a different synthetic run. This site calculates metrics from its own trained model and never presents that number as a measured result.</div><p class="card-sub" style="line-height:1.9;margin:15px 0">Upload your own CSV and confirm the label mapping. Normal, Benign, 0, False and Legitimate are suggested Normal tokens; all other selected target values map to Suspicious.</p></section></div><div class="grid2"><section class="card"><h2>Evaluation and explanation limits</h2><p class="card-sub" style="line-height:1.9;margin:15px 0">Precision, recall and F1 refer to the Suspicious class. Macro-F1 averages the two class F1-scores and is used for permutation importance. Correlated features can affect importance; local sensitivity is neither SHAP nor a causal explanation.</p><p class="card-sub" style="line-height:1.9">Random splits may overestimate generalization for related flows or capture sessions. Public-dataset validation, group/time-based splitting, calibration, drift testing and operational validation remain future work.</p></section><section class="card"><h2>Scope and privacy</h2><p class="card-sub" style="line-height:1.9;margin:15px 0">CSV parsing, preprocessing, model training and inference happen in your browser. Source datasets, fitted models, scored batches and review decisions are stored in IndexedDB on this device. Saved experiments survive refresh and can be restored from Experiment history. Exports are local downloads; clearing browser site storage removes the saved workflows. This website does not capture traffic, inspect packet payloads, attribute attacks, prevent intrusions or configure firewalls.</p><p class="card-sub" style="line-height:1.9">Interface fonts may be fetched externally; the interface falls back to system fonts if unavailable. No dataset content is sent with font requests.</p></section></div><section class="card about-section"><h2>Report context and references</h2><p>Mini project · Computer Networks · Unitedworld Institute of Technology, Karnavati University · July–November 2026. Report authors: Het Detroja and Mahir Patel.</p><p style="display:flex;gap:18px;flex-wrap:wrap"><a class="line-link" href="https://www.unb.ca/cic/datasets/ids-2017.html" target="_blank" rel="noreferrer">CIC-IDS2017 dataset ↗</a><a class="line-link" href="https://scikit-learn.org/stable/modules/permutation_importance.html" target="_blank" rel="noreferrer">Permutation importance reference ↗</a></p></section>`}
function render(){document.title=views[state.view][0]+' · FlowLens';document.getElementById('app').innerHTML=shell(({workflows,batch:batchView,reviews:reviewsView,history:historyView,overview,dataset,evaluation,explainability,analyzer,notes})[state.view]());bind()}
function updateTable(){let el=document.querySelector('.table-card');if(el){let active=document.activeElement?.id;let pos=document.getElementById('flow-search')?.selectionStart;el.outerHTML=flowTable();bindTable();if(active==='flow-search'){let input=document.getElementById(active);input.focus();input.setSelectionRange(pos,pos)}}}
function bindTable(){document.getElementById('flow-search')?.addEventListener('input',e=>{state.search=e.target.value;state.page=0;updateTable()});document.getElementById('flow-filter')?.addEventListener('change',e=>{state.filter=e.target.value;state.page=0;updateTable()})}
function bind(){WF.bind();bindTable();document.getElementById('csv-file')?.addEventListener('change',e=>readFile(e.target.files[0]));const zone=document.getElementById('drop-zone');if(zone){zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag')});zone.addEventListener('dragleave',()=>zone.classList.remove('drag'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag');readFile(e.dataTransfer.files[0])})}document.getElementById('label-column')?.addEventListener('change',e=>{state.label=e.target.value;mapDefaults();render()});document.getElementById('flow-select')?.addEventListener('change',e=>{state.selected=+e.target.value;state.local=null;explainSelected()});document.getElementById('analyze-form')?.addEventListener('submit',e=>{e.preventDefault();let form=e.target;if(!form.reportValidity())return;form.querySelectorAll('[data-input]').forEach(el=>{let s=state.run.schema.find(s=>s.name===el.dataset.input);state.formValues[el.dataset.input]=s.type==='numeric'?Number(el.value):el.value});state.worker.postMessage({type:'predict',row:state.formValues,id:'custom-'+(++state.predictRevision)})});document.querySelectorAll('[data-input]').forEach(el=>el.addEventListener('input',()=>{state.predictRevision++;state.prediction=null;document.getElementById('prediction-result').innerHTML=analyzerResults();document.getElementById('custom-sensitivity').innerHTML=''}))}
document.addEventListener('click',e=>{let v=e.target.closest('[data-view]');if(v){navigate(v.dataset.view);return}let x=e.target.closest('[data-explain]');if(x){state.selected=state.run.tests.findIndex(t=>t.id===+x.dataset.explain);state.local=null;navigate('explainability');return}let p=e.target.closest('[data-page]');if(p&&!p.disabled){state.page=+p.dataset.page;updateTable();return}let a=e.target.closest('[data-action]')?.dataset.action;if(a){if(a==='menu'){state.menu=!state.menu;document.querySelector('.sidebar').classList.toggle('open',state.menu);document.querySelector('.mobile-scrim').classList.toggle('open',state.menu)}if(a==='train')startTraining();if(a==='cancel'){WF.cancel();state.worker?.terminate();state.busy=false;state.run=null;state.error='Training cancelled. Your dataset is ready for another run.';render()}if(a==='sample')download('synthetic_network_flows.csv',FlowData.csv(FlowData.demo()),'text/csv');if(a==='reset-demo'){if(WF.working())return notify('Wait for the active workflow to finish.');loadRows(FlowData.demo(),'synthetic_network_flows.csv',true);render();notify('Synthetic demonstration dataset loaded')}if(a==='export')download('flowlens_experiment.json',JSON.stringify(exportRun(),null,2),'application/json');if(a==='reset-form'){state.predictRevision++;state.prediction=null;state.formValues=Object.fromEntries(state.run.schema.map(s=>[s.name,s.typical]));render()}if(a==='export-flow')download('flowlens_custom_analysis.json',JSON.stringify({source:state.file,synthetic:state.demo,model:exportRun().configuration,values:state.formValues,...state.prediction,caution:'Educational model output; uncalibrated probability, not proof of intrusion.'},null,2),'application/json');if(a==='use-flow'){state.predictRevision++;let t=state.run.tests[state.selected];state.formValues={...t.values};state.prediction=null;navigate('analyzer')}}});
document.addEventListener('change',e=>{let el=e.target;if(el.matches('[data-feature]')){el.checked?state.excluded.delete(el.dataset.feature):state.excluded.add(el.dataset.feature);render()}if(el.matches('[data-normal]')){el.checked?state.normalLabels.push(el.dataset.normal):state.normalLabels=state.normalLabels.filter(v=>v!==el.dataset.normal);render()}});
function mapDefaults(){let values=[...new Set(state.rows.map(r=>String(r[state.label]??'')))];state.normalLabels=values.filter(v=>['normal','benign','0','false','legitimate'].includes(v.trim().toLowerCase()))}
function loadRows(rows,file,demo){WF.datasetChanged();state.worker?.terminate();Object.assign(state,{rows,file,demo,run:null,local:null,prediction:null,selected:0,page:0,search:'',filter:'all',error:''});let headers=Object.keys(rows[0]);state.label=headers.find(h=>/^(label|class|target|attack_cat|category|analyst_label)$/i.test(h.trim()))||headers[headers.length-1];state.excluded=new Set(headers.filter(h=>/^(id|index|source_case_id|flow[ _]?id|src[ _]?ip|dst[ _]?ip|source[ _]?ip|destination[ _]?ip|timestamp|unnamed.*)$/i.test(h)));mapDefaults()}
async function readFile(file){if(!file)return;if(WF.working())return notify('Wait for the active workflow to finish.');try{if(!file.name.toLowerCase().endsWith('.csv'))throw Error('Please select a .csv file.');if(file.size>5*1024*1024)throw Error('File exceeds 5 MB. Use a smaller experiment subset.');let rows=FlowData.parse(await file.text());if(rows.length<20)throw Error('Use at least 20 labelled records.');loadRows(rows,file.name,false);render();notify('CSV loaded. Review target labels and feature selection.')}catch(err){state.error=err.message;render()}}
function attachWorker(){
 state.predictRevision++;state.worker?.terminate();state.worker=new Worker('engine.js');
 state.worker.onerror=()=>{let message='The model worker could not finish. Try fewer records or features.';state.busy=false;WF.fail(message);state.error=message;render()};
 state.worker.onmessage=e=>{let m=e.data;
  if(m.type==='progress'){state.progress=m.progress;state.progressText=m.text;let t=document.getElementById('progress-title'),b=document.getElementById('progress-bar');if(t)t.textContent=m.text+' · '+m.progress+'%';if(b)b.style.width=m.progress+'%'}
  if(m.type==='error'){state.busy=false;WF.fail(m.message);state.error=m.message;render();return}
  if(m.type==='trained'){state.run=m.result;state.busy=false;state.selected=0;state.page=0;state.formValues=Object.fromEntries(m.result.schema.map(s=>[s.name,s.typical]));render();if(state.view==='explainability')explainSelected()}
  if(m.type==='explain'&&m.id===state.selected){state.local=m.result;if(state.view==='explainability')document.getElementById('local-result').innerHTML=localResults(state.run.tests[state.selected])}
  if(m.type==='predict'&&m.id==='custom-'+state.predictRevision){state.prediction=m.result;if(state.view==='analyzer'){document.getElementById('prediction-result').innerHTML=analyzerResults();document.getElementById('custom-sensitivity').innerHTML=sensitivity(m.result);notify('Flow analysis complete')}}
  WF.handle(m);
 };
}
function startTraining(){
 if(WF.working())return notify('Wait for the active workflow to finish.');let features=WF.features();
 try{FlowWorkflow.inspect(state.rows,state.label,features,state.normalLabels)}catch(e){state.error=e.message;state.view='dataset';render();return}
 WF.begin();attachWorker();state.busy=true;state.run=null;state.local=null;state.prediction=null;state.error='';state.progress=0;state.progressText='Preparing stratified train/test split';state.view='workflows';render();window.scrollTo({top:0,behavior:'instant'});state.worker.postMessage({type:'train',rows:state.rows,label:state.label,features,normalLabels:state.normalLabels});
}
function explainSelected(){if(state.run)state.worker.postMessage({type:'explain',id:state.selected,row:state.run.tests[state.selected].values})}
function exportRun(){let r=state.run;return {application:'FlowLens',implementation:'Browser-native JavaScript Random Forest; independent of scikit-learn',dataset:state.file,synthetic:state.demo,exportedAt:new Date().toISOString(),trainedAt:r.trainedAt,configuration:{trees:r.trees,seed:r.seed,split:r.split,maxDepth:r.maxDepth,minLeaf:r.minLeaf,classWeight:'balanced',maxFeatureCandidatesPerNode:'floor(sqrt(encoded dimensions))',splitCandidates:'up to 10 quantiles per feature',threshold:.5,trainCount:r.trainCount,testCount:r.testCount,target:r.label,normalLabels:r.normalLabels,features:r.features},metrics:r.scores,permutationImportance:r.importance,permutationRepeats:r.permutationRepeats,schema:r.schema,dataQuality:{missingFeatureCells:r.missing,exactDuplicates:r.duplicates,removed:r.dropped},testPredictions:r.tests,caution:'Educational offline classification; probabilities uncalibrated. Synthetic results are not real-world detection performance.'}}
function download(filename,body,type){let url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Downloaded '+filename)}
render();
WF.init();
